/* ExpatGuideME service worker (generated by _src/build.py — edit _src/sw.template.js).
 * - Pages, site.js and site.css: always checked with the server first (cache: "no-cache"),
 *   so new rates and fixes show on the next visit; the saved copy is used only offline.
 * - The calculators (end of service, vacation, family cost, embassy, ID) are saved
 *   on install in English, and in the visitor's language when site.js asks.
 * - Images and other static files: served from the cache and refreshed in the background.
 * - /api/ and other websites (ads, analytics) are never cached.
 */
const VERSION = "720366e556";
const CACHE = "egm-" + VERSION;
const CORE = [
  "/", "/offline.html", "/assets/site.css", "/assets/site.js", "/assets/favicon.svg",
  "/assets/icon-192.png", "/manifest.webmanifest",
  "/end-of-service.html", "/vacation-calculator.html", "/family-cost.html",
  "/embassy-services.html", "/id-residency.html", "/exchange-rate.html", "/gold-rate.html"
];
const FONT_CACHE = "egm-fonts";

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE).then((c) => Promise.all(CORE.map((u) => c.add(new Request(u, { cache: "reload" })).catch(() => null))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith("egm-") && k !== CACHE && k !== FONT_CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("message", (event) => {
  const d = event.data || {};
  if (d.type === "warm" && Array.isArray(d.urls)) {
    const urls = d.urls.filter((u) => typeof u === "string" && u.startsWith("/") && !u.startsWith("/api/")).slice(0, 20);
    event.waitUntil(caches.open(CACHE).then((c) => Promise.all(urls.map((u) => c.match(u).then((hit) => hit || c.add(u).catch(() => null))))));
  }
});

function isFont(url) {
  return url.hostname === "fonts.googleapis.com" || url.hostname === "fonts.gstatic.com";
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);

  if (isFont(url)) {
    event.respondWith(
      caches.open(FONT_CACHE).then((c) => c.match(req).then((hit) => hit || fetch(req).then((res) => { if (res.ok || res.type === "opaque") c.put(req, res.clone()); return res; })))
    );
    return;
  }
  if (url.origin !== self.location.origin || url.pathname.startsWith("/api/") || url.pathname === "/sw.js") return;

  if (req.mode === "navigate" || (req.headers.get("accept") || "").includes("text/html")) {
    event.respondWith(
      fetch(req.url, { cache: "no-cache", credentials: "same-origin" }).then((res) => {
        if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(url.pathname, copy)); }
        return res;
      }).catch(() => caches.open(CACHE).then((c) =>
        c.match(url.pathname).then((hit) => hit || c.match(url.pathname.replace(/\/$/, "/index.html"))).then((hit) => hit || c.match("/offline.html"))
      ))
    );
    return;
  }

  if (/\.(js|css|json)$/.test(url.pathname)) {
    event.respondWith(
      fetch(req.url, { cache: "no-cache", credentials: "same-origin" }).then((res) => {
        if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(url.pathname, copy)); }
        return res;
      }).catch(() => caches.open(CACHE).then((c) => c.match(url.pathname)))
    );
    return;
  }

  event.respondWith(
    caches.open(CACHE).then((c) => c.match(req, { ignoreSearch: true }).then((hit) => {
      const net = fetch(req).then((res) => { if (res.ok) c.put(req, res.clone()); return res; }).catch(() => hit);
      return hit || net;
    }))
  );
});
